const id = $json.senderId || $json.clientEmail || '';
const name = $json.clientName || '';
return [{ json: { ...$json, mem_search_key: id || name } }];

const rows = $input.all();
const prev = $('MEM-READ-1 Préparer Clé').first().json;
let ficheClient = null;
let historiqueTexts = [];
let logosDropbox = [];
for (const row of rows) {
  const r = row.json;
  if (!ficheClient && (r.senderId === prev.senderId || r.email === prev.clientEmail)) ficheClient = r;
  if (r.client_key === prev.mem_search_key || r.senderId === prev.senderId) {
    if (r.type === 'conversation') historiqueTexts.push('[' + (r.date||'') + '] ' + (r.category||'') + ': ' + (r.summary||r.message||''));
    if (r.type === 'image' || r.type === 'logo') logosDropbox.push({ path: r.dropbox_path, filename: r.filename, date: r.date });
  }
}
const memoire = { client_connu: ficheClient !== null, prenom: ficheClient?.prenom||ficheClient?.clientName||'', email: ficheClient?.email||prev.clientEmail||'', nb_commandes: ficheClient?.nb_commandes||0, derniere_commande: ficheClient?.derniere_commande||'', preferences: ficheClient?.preferences||'', historique: historiqueTexts.slice(-5), logos_stockes: logosDropbox };
let contexte_memoire = '';
if (memoire.client_connu) {
  contexte_memoire += 'CLIENT CONNU : ' + memoire.prenom + ' | ' + memoire.nb_commandes + ' commande(s)';
  if (memoire.derniere_commande) contexte_memoire += ' | Derniere commande : ' + memoire.derniere_commande;
  if (memoire.preferences) contexte_memoire += '\nPreferences : ' + memoire.preferences;
}
if (memoire.historique.length > 0) contexte_memoire += '\n\nHISTORIQUE RECENT :\n' + memoire.historique.join('\n');
if (memoire.logos_stockes.length > 0) {
  const logoList = memoire.logos_stockes.map(l => '- ' + l.filename + ' (' + l.date + ')').join('\n');
  contexte_memoire += '\n\nLOGOS DEJA RECUS :\n' + logoList;
}
return [{ json: { ...prev, memoire, contexte_memoire: contexte_memoire || 'Nouveau client.' }}];

// Gmail/FB send nodes replace $json with API response — recover original data via node ref
const hasSrc = $json.senderId || $json.clientEmail || $json.text;
const fmtData = $('T5 Formater Réponse1').first().json;
const src = hasSrc ? $json : ((fmtData && (fmtData.senderId || fmtData.clientEmail || fmtData.reponse)) ? fmtData : $json);
const now = new Date().toISOString().substring(0,16).replace('T',' ');
const clientKey = src.senderId || src.clientEmail || 'inconnu';
const ligneHistorique = { date: now, client_key: clientKey, senderId: src.senderId||'', email: src.clientEmail||'', clientName: src.clientName||'', source: src.source||'messenger', category: src.action||src.category||'', message: (src.text||'').substring(0,300), reponse: (src.reponse||'').substring(0,500), type: 'conversation', dropbox_path: src.dropbox_path||'', filename: src.filename||'' };
if (src.action === 'TRAITEMENT_IMAGE' && src.dropbox_path) { ligneHistorique.type = 'logo'; ligneHistorique.filename = src.filename||'logo'; }
const ligneClient = { date_maj: now, senderId: src.senderId||'', email: src.clientEmail||'', prenom: src.clientName||'', source: src.source||'', derniere_categorie: src.action||'', derniere_commande: src.action==='DEVIS'?now:'', logos_count: src.action==='TRAITEMENT_IMAGE'?1:0 };
return [{ json: { ligneHistorique, ligneClient, ...src } }];

const source = .body ? 'messenger' : 'gmail';

// ── Anti-boucle : adresse du compte HCS lui-même ──────────────
const OWN_EMAIL = 'highcoffeeshirt@gmail.com';

let text = '', senderId = '', clientEmail = '', clientName = '',
    attachments = [], hasAttachments = false;

if (source === 'messenger') {
  const entry  = (.body?.entry || [])[0];
  const event  = (entry?.messaging || [])[0];
  if (!event || !event.message || event.message.is_echo) return [];
  text          = event.message.text || '';
  senderId      = event.sender.id;
  clientName    = senderId;
  attachments   = event.message.attachments || [];
  hasAttachments = attachments.length > 0;

} else {
  const from  = (.from?.value || [])[0] || {};
  clientEmail = (from.address || '').toLowerCase();
  clientName  = from.name || clientEmail;
  senderId    = '';

  if (clientEmail === OWN_EMAIL) return [];

  const autoSubmitted = (.headers?.['auto-submitted'] || '').toLowerCase();
  if (autoSubmitted && autoSubmitted !== 'no') return [];

  const skipPatterns = [
    'no-reply', 'noreply', 'no_reply', 'mailer-daemon',
    'postmaster', 'notifications@', 'accounts.google',
    'security@', 'support@google', 'bounce', 'donotreply',
    'do-not-reply', 'auto-reply', 'automaticreply',
    'unsubscribe', 'newsletter', 'automailer',
    'mail.klaviyo', 'klaviyomail', 'stickerbros'
  ];
  if (skipPatterns.some(p => clientEmail.includes(p))) return [];

  text = .text || .snippet || '';
  if (!text || text.trim().length < 5) return [];
}

text       = text.replace(/["
	]/g, ' ').trim();
clientName = String(clientName).replace(/["
	]/g, ' ').trim();

return [{ json: { source, text, senderId, clientEmail, clientName, attachments, hasAttachments } }];

const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';
const prev = $('T1 Normaliser Message1').first().json;
let cat = 'INFO_SERVICES', confidence = 0.5, reason = '';
if (prev.hasAttachments) return [{ json: { ...prev, category: 'TRAITEMENT_IMAGE', confidence: '100%', reason: 'Pieces jointes detectees' } }];
try {
  const p = JSON.parse(raw);
  const valid = ['DEVIS','INFO_SERVICES','INFO_PRODUITS','MOCKUP','TRAITEMENT_IMAGE'];
  cat = valid.includes(p.category) ? p.category : 'INFO_SERVICES';
  confidence = p.confidence || 0.5;
  reason = p.reason || '';
} catch(e) {}
return [{ json: { ...prev, category: cat, confidence: Math.round(confidence*100)+'%', reason } }];

const text = ($json.text || '').toLowerCase();
let info = '';
if (text.includes('dtf') || text.includes('impression')) info = 'DTF recto : des 1500 XPF | recto-verso : des 2200 XPF | delai 2-3j';
else if (text.includes('broderie')) info = 'Broderie logo : des 2000 XPF | delai 3-5j | rendu premium';
else if (text.includes('vinyle') || text.includes('vinyl')) info = 'Vinyle thermocollant : des 800 XPF/piece | delai 1-2j';
else if (text.includes('delai') || text.includes('livraison')) info = 'Delais : DTF 2-3j | Broderie 3-5j | Grande serie 7-10j | Livraison Tahiti + iles';
else info = 'DTF des 1500 XPF | Broderie des 2000 XPF | Vinyle des 800 XPF — tarifs degressifs des 10 pieces';
return [{ json: { ...($json), action:'INFO_SERVICES', contexte_reponse: info } }];

const text = ($json.text || '').toLowerCase();
let info = '';
if (text.includes('polo')) info = 'Polo coton pique : 1800-2500 XPF | Polo technique : 2200-3000 XPF';
else if (text.includes('hoodie') || text.includes('sweat')) info = 'Hoodie : 3500-5000 XPF | Sweat col rond : 2800-4000 XPF';
else if (text.includes('casquette') || text.includes('cap')) info = 'Casquette 5 panneaux : 1500-2000 XPF | Snapback : 1800-2500 XPF';
else if (text.includes('lycra') || text.includes('rashguard')) info = 'Rashguard manches longues : 4500-6000 XPF | Lycra : sur devis';
else info = 'T-shirt : des 600 XPF | Polo : des 1800 XPF | Hoodie : des 3500 XPF | Casquette : des 1500 XPF';
return [{ json: { ...($json), action:'INFO_PRODUITS', contexte_reponse: info } }];

const attachments = $json.attachments || [];
const imageUrl = attachments.length > 0 ? (attachments[0].payload?.url || '') : '';
return [{ json: { ...($json), action: 'TRAITEMENT_IMAGE', image_url: imageUrl, picwish_ready: imageUrl.length > 0, dropbox_folder: '/Clients/' + $json.clientName.replace(/[^a-zA-Z0-9_ -]/g,'').replace(/ +/g,'_').trim() + '/Logos', contexte_reponse: imageUrl ? 'Image recue, detourage en cours via PicWish.' : 'Aucune image trouvee.' }}];

const cat = $json.action || $json.category;
const clientSlug = ($json.clientName || 'Client_inconnu').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_ -]/g,'').replace(/ +/g,'_').trim();
const ts = new Date().toISOString().substring(0,10);
const source = $json.source || 'inconnu';
const baseFolder = source === 'gmail' ? '/HCS/2026/CLIENTS/' + new Date().toLocaleString('fr-FR',{month:'long'}) + '/' + clientSlug : '/HCS/2026/CLIENTS/Messenger/' + clientSlug;
let folder = baseFolder;
let filename = cat + '_' + ts + '.txt';
let content = JSON.stringify($json, null, 2);
if (cat === 'TRAITEMENT_IMAGE') {
  const picwishUrl = $json.image_url || $json.url || '';
  filename = 'logo_' + ts + '.png';
  folder = baseFolder + '/logos';
  content = picwishUrl;
  return [{ json: { ...$json, dropbox_path: folder + '/' + filename, dropbox_content: content, picwish_url: picwishUrl } }];
}
if (cat === 'MOCKUP') folder = baseFolder + '/mockups';
if (cat === 'DEVIS') folder = baseFolder + '/devis';
return [{ json: { ...$json, dropbox_path: folder + '/' + filename, dropbox_content: content } }];

