const raw = $input.first().json?.choices?.[0]?.message?.content || '';
const prev = $('T4 Préparer Dropbox1').first().json || {};
const effectiveSource = prev.source || (prev.senderId ? 'messenger' : 'gmail');
return [{ json: { senderId: prev.senderId||'', pageId: prev.pageId||'', clientEmail: prev.clientEmail||'', source: effectiveSource, action: prev.action||prev.category||'', reponse: raw, quickReplies: [{ content_type:'text', title:'Devis', payload:'DEVIS' }, { content_type:'text', title:'Tarifs', payload:'TARIFS' }, { content_type:'text', title:'Mockup', payload:'MOCKUP' }] }}];

const body = $input.first().json.body;
if (!body || !body.entry) return [];
const messages = [];
for (const entry of body.entry) {
  if (!entry.messaging) continue;
  for (const event of entry.messaging) {
    if (event.message && !event.message.is_echo) {
      messages.push({ senderId: event.sender.id, recipientId: event.recipient.id, timestamp: event.timestamp, messageId: event.message.mid, text: event.message.text || '', attachments: event.message.attachments || [], pageId: entry.id });
    } else if (event.postback) {
      messages.push({ senderId: event.sender.id, recipientId: event.recipient.id, timestamp: event.timestamp, messageId: 'postback_' + Date.now(), text: event.postback.title + ' [POSTBACK: ' + event.postback.payload + ']', attachments: [], pageId: entry.id, isPostback: true, payload: event.postback.payload });
    }
  }
}
return messages;

const rows = $input.all();
const prev = $('MEM-READ-3 Injecter Mémoire').first().json;
let services = [], produits = [];
for (const row of rows) {
  const r = row.json;
  if (!r || !r.nom) continue;
  let ligne = r.nom;
  if (r.prix_min && r.prix_max) ligne += ' : ' + r.prix_min + '-' + r.prix_max + ' ' + (r.unite||'XPF');
  else if (r.prix_min) ligne += ' : des ' + r.prix_min + ' ' + (r.unite||'XPF');
  if (r.delai) ligne += ' | delai ' + r.delai;
  if (r.description) ligne += ' - ' + r.description;
  const cat = (r.categorie||'').toUpperCase().trim();
  if (cat === 'SERVICE') services.push(ligne);
  else if (cat === 'PRODUIT') produits.push(ligne);
}
let catalogue_texte = '';
if (services.length > 0) catalogue_texte += 'SERVICES & TARIFS :\n' + services.map(s => '- ' + s).join('\n');
if (produits.length > 0) catalogue_texte += '\n\nPRODUITS :\n' + produits.map(p => '- ' + p).join('\n');
if (!catalogue_texte.trim()) catalogue_texte = 'DTF recto 1500-3000 XPF/piece | Broderie 2000-3500 XPF | Vinyle 800-2500 XPF';
return [{ json: { ...prev, catalogue_texte, catalogue_charge: rows.length > 0 }}];

const clean = s => String(s||'').replace(/["\n\r\t\\]/g,' ');
const text = clean($json.text).substring(0,600);
const memoire = clean($json.contexte_memoire||'Nouveau client.').substring(0,400);
const catalogue = clean($json.catalogue_texte||'').substring(0,500);
const clientName = clean($json.clientName||$json.senderId||'Client').substring(0,80);
return [{ json: { ...$json, _dv_text: text, _dv_mem: memoire, _dv_cat: catalogue, _dv_client: clientName } }];

