const raw = ($input.first().json?.choices?.[0]?.message?.content) || '{}';
const prev = $('DEVIS-1 Préparer Extraction').first().json;
let d = {};
try { d = JSON.parse(raw); } catch(e) {}
const ref = 'DEV-' + Date.now();
const now = new Date().toISOString().substring(0,16).replace('T',' ');
const qte = d.quantite || 1;
const pu = d.prix_unitaire || 1500;
const remise = d.remise_pct || 0;
const total = d.prix_total || Math.round(pu * qte * (1 - remise/100));
const lignes = [{ article: d.article || 'Personnalisation textile', qte, pu, technique: d.technique || 'DTF', remise }];
return [{ json: {
  ...prev,
  devis_ref: ref,
  devis_article: d.article || 'Personnalisation textile',
  devis_qte: qte,
  devis_technique: d.technique || 'DTF',
  devis_pu: pu,
  devis_remise: remise,
  devis_total: total,
  devis_delai: d.delai || '3-5 jours',
  message_client: d.message_client || 'Votre devis est pret. Contactez-nous pour confirmer.',
  devis_notes: d.notes || '',
  devis_lignes: JSON.stringify(lignes),
  devis_created_at: now
}}];

const apiResp = $input.first().json;
const ctx = $('DEVIS-3 Parser Devis').first().json;
const devisId = String(apiResp.id || apiResp.data?.id || apiResp.item?.id || '');
const execId = $execution.id;
const baseUrl = 'https://hcstahiti.app.n8n.cloud/webhook-waiting/' + execId;
const approveUrl = baseUrl + '?approved=1&devis_id=' + devisId;
const rejectUrl  = baseUrl + '?approved=0&devis_id=' + devisId;
const erpUrl     = 'https://highcoffeeshirts.com/erp/#devis';
const emailHtml =
  '<h2 style="color:#1e40af;font-family:sans-serif">Devis a approuver — High Coffee Shirt</h2>' +
  '<table style="font-family:sans-serif;font-size:14px;border-collapse:collapse" border="1" cellpadding="8">' +
  '<tr><td><b>Client</b></td><td>' + (ctx.clientName || ctx.senderId || 'N/A') + '</td></tr>' +
  '<tr><td><b>Canal</b></td><td>' + (ctx.source || 'N/A') + '</td></tr>' +
  '<tr><td><b>Reference</b></td><td>' + ctx.devis_ref + '</td></tr>' +
  '<tr><td><b>Article</b></td><td>' + ctx.devis_article + ' x' + ctx.devis_qte + ' (' + ctx.devis_technique + ')</td></tr>' +
  '<tr><td><b>Prix unitaire</b></td><td>' + ctx.devis_pu + ' XPF (-' + ctx.devis_remise + '%)</td></tr>' +
  '<tr><td><b>Total</b></td><td><b>' + ctx.devis_total + ' XPF</b></td></tr>' +
  '<tr><td><b>Delai</b></td><td>' + ctx.devis_delai + '</td></tr>' +
  '</table>' +
  '<h3 style="font-family:sans-serif">Message original du client :</h3>' +
  '<p style="font-family:sans-serif;background:#f3f4f6;padding:10px;border-radius:4px">' + (ctx.text || '').substring(0, 500) + '</p>' +
  '<h3 style="font-family:sans-serif">Devis redige par IA :</h3>' +
  '<p style="font-family:sans-serif;background:#eff6ff;padding:10px;border-radius:4px">' + (ctx.message_client || '').replace(/\n/g, '<br>') + '</p>' +
  '<hr>' +
  '<h3 style="font-family:sans-serif">Actions :</h3>' +
  '<p><a href="' + approveUrl + '" style="display:inline-block;background:#16a34a;color:white;padding:12px 28px;border-radius:6px;text-decoration:none;font-family:sans-serif;font-size:16px;margin:4px">Approuver et envoyer</a></p>' +
  '<p><a href="' + erpUrl + '" style="display:inline-block;background:#2563eb;color:white;padding:12px 28px;border-radius:6px;text-decoration:none;font-family:sans-serif;font-size:16px;margin:4px">Modifier dans ERP puis approuver</a></p>' +
  '<p><a href="' + rejectUrl + '" style="display:inline-block;background:#dc2626;color:white;padding:12px 28px;border-radius:6px;text-decoration:none;font-family:sans-serif;font-size:16px;margin:4px">Rejeter</a></p>' +
  '<p style="font-family:sans-serif;color:#888;font-size:11px">ID MySQL: ' + devisId + ' | Expiration: 24h | ExecID: ' + execId + '</p>';
return [{ json: { ...ctx, devis_mysql_id: devisId, admin_email_html: emailHtml, approve_url: approveUrl, reject_url: rejectUrl } }];

const query = ($json.query) || ($json.body) || {};
const approved = String(query.approved) === '1';
const devisId = String(query.devis_id || query.devisId || '');
const ctx = $('DEVIS-5 Préparer Email Admin').first().json;
return [{ json: { ...ctx, approved, devis_mysql_id: devisId || ctx.devis_mysql_id || '', wait_query: query } }];

const apiResp = $input.first().json;
const ctx = $('DEVIS-8 Restaurer Contexte').first().json;
const devis = apiResp.item || apiResp.data || apiResp || {};
const notes = (devis.notes || ctx.message_client || 'Votre devis est disponible.');
const ref = devis.ref || ctx.devis_ref || '';
const reponse =
  'Votre devis High Coffee Shirt\n\n' +
  'Reference : ' + ref + '\n\n' +
  notes + '\n\n' +
  'Ce devis a ete valide par notre equipe.\n' +
  'Pour confirmer votre commande, repondez a ce message ou ecrivez a : highcoffeeshirt@gmail.com\n' +
  'High Coffee Shirt — Personnalisation textile Tahiti';
const reponse_messenger =
  '✅ Devis valide — ' + ref + '\n\n' +
  notes.substring(0, 380) + '\n\n' +
  'Pour confirmer : highcoffeeshirt@gmail.com ☕';
return [{ json: { ...ctx, reponse, reponse_messenger, quickReplies: [{ content_type:'text', title:'Confirmer commande', payload:'CONFIRMER' }, { content_type:'text', title:'Questions', payload:'QUESTIONS' }], devis_statut: 'approuve', action: 'DEVIS' } }];

const ctx = $('DEVIS-8 Restaurer Contexte').first().json;
const reponse =
  'Bonjour ' + (ctx.clientName || '') + ',\n\n' +
  'Apres examen de votre demande, notre equipe ne peut pas etablir ce devis dans les conditions demandees.\n\n' +
  'Nous vous invitons a nous recontacter pour reformuler votre demande :\n' +
  'Email : highcoffeeshirt@gmail.com\n' +
  'Nous restons disponibles pour vous aider.\n\n' +
  'High Coffee Shirt — Tahiti';
const reponse_messenger =
  '⚠️ Bonjour,\n\n' +
  'Nous ne pouvons pas traiter ce devis actuellement.\n\n' +
  'Recontactez-nous : highcoffeeshirt@gmail.com\n' +
  'High Coffee Shirt Tahiti ☕';
return [{ json: { ...ctx, reponse, reponse_messenger, quickReplies: [{ content_type:'text', title:'Nouveau devis', payload:'DEVIS' }, { content_type:'text', title:'Nous contacter', payload:'CONTACT' }], devis_statut: 'rejete', action: 'DEVIS' } }];

const ctx = $('DEVIS-8 Restaurer Contexte').first().json;
const approved = $('DEVIS-11 Format Réponse Approuvée').first().json;
const rejected = $('DEVIS-12 Format Rejet').first().json;
const sent = (approved && approved.devis_statut) ? approved : (rejected && rejected.devis_statut) ? rejected : {};
return [{ json: { ...ctx, reponse: sent.reponse||'', reponse_messenger: sent.reponse_messenger||'', devis_statut: sent.devis_statut||'traite', action: 'DEVIS' } }];
